// written on", and why: the unit's own, else its property's, else the org
// default. A soft-deleted assignment is skipped, never an error.
func (q *Queries) ResolveUnitTemplate(ctx context.Context, arg ResolveUnitTemplateParams) (ResolveUnitTemplateRow, error) {
	row := q.db.QueryRow(ctx, resolveUnitTemplate, arg.OrgID, arg.UnitID)
	var i ResolveUnitTemplateRow
	err := row.Scan(&i.ID, &i.Name, &i.Source)
	return i, err
}

