const setScheduleAmount = `-- name: SetScheduleAmount :one

UPDATE payment_schedules
SET amount = $1,
    status = CASE
        WHEN status IN ('waived', 'written_off') THEN status
        WHEN paid_amount >= $1::bigint THEN 'paid'
        WHEN due_date + $2::int < CURRENT_DATE THEN 'overdue'
        WHEN paid_amount > 0 THEN 'partial'
        ELSE 'pending'
    END
WHERE org_id = $3 AND id = $4 AND deleted_at IS NULL
RETURNING id, org_id, contract_id, period_start, period_end, due_date, amount, status, created_at, updated_at, deleted_at, paid_amount, written_off_at, written_off_by_user_id, write_off_reason, original_amount, adjustment_kind, adjustment_reason, adjusted_at, adjusted_by_user_id, backfill_batch_id
`

type SetScheduleAmountParams struct {
	Amount    int64       `json:"amount"`
	GraceDays int32       `json:"grace_days"`
	OrgID     pgtype.UUID `json:"org_id"`
	ID        pgtype.UUID `json:"id"`
}

// ------------------------------------------------ §22.5 settle-up, deposits --
// SetScheduleAmount re-prices one period (pro-rata move-out) and recomputes
// its status from its own money and dates.
func (q *Queries) SetScheduleAmount(ctx context.Context, arg SetScheduleAmountParams) (PaymentSchedule, error) {
	row := q.db.QueryRow(ctx, setScheduleAmount,
		arg.Amount,
		arg.GraceDays,
		arg.OrgID,
		arg.ID,
	)
	var i PaymentSchedule
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.ContractID,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.DueDate,
		&i.Amount,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.PaidAmount,
		&i.WrittenOffAt,
		&i.WrittenOffByUserID,
		&i.WriteOffReason,
		&i.OriginalAmount,
		&i.AdjustmentKind,
		&i.AdjustmentReason,
		&i.AdjustedAt,
		&i.AdjustedByUserID,
		&i.BackfillBatchID,
	)
	return i, err
}

