const setUnitsTemplate = `-- name: SetUnitsTemplate :many
UPDATE units SET contract_template_id = $1
WHERE org_id = $2 AND id = ANY($3::uuid[]) AND deleted_at IS NULL
RETURNING id
`

type SetUnitsTemplateParams struct {
	TemplateID pgtype.UUID   `json:"template_id"`
	OrgID      pgtype.UUID   `json:"org_id"`
	UnitIds    []pgtype.UUID `json:"unit_ids"`
}

// SetUnitsTemplate assigns (or, with NULL, clears) the template of a set of
// the org's units in one statement. Ids from another org match nothing.
func (q *Queries) SetUnitsTemplate(ctx context.Context, arg SetUnitsTemplateParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, setUnitsTemplate, arg.TemplateID, arg.OrgID, arg.UnitIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

